baseParser.source:
function (input, object) {
            var data = new game.ETBaseGameData();
            var node = input.getElementsByTagName("BGInfo")[0];
            if (node != null) {
                var attributes = node.attributes;
                var nodeChildren = node.childNodes;
                data.totalWagerWin = parseInt(attributes.getNamedItem("totalWagerWin").value);
                data.bgWinnings = parseInt(attributes.getNamedItem("bgWinnings").value);
                data.baseGameSpinsRemaining = parseInt(attributes.getNamedItem("baseGameSpinsRemaining").value);
                data.isBigBet = parseInt(attributes.getNamedItem("isBigBet").value) == 1;
                data.isMaxWin = parseInt(attributes.getNamedItem("isMaxWin").value) == 1;
                data.bonusChief = attributes.getNamedItem("chiefWin") ? parseInt(attributes.getNamedItem("chiefWin").value) == 1 : false;
            }
            object.baseGameData = data;
        }

