gambleParser.source:
function (input, object) {
            var data = new game.GambleData();
            var node = input.getElementsByTagName("GambleInfo")[0];
            if (node != null) {
                var attributes = node.attributes;
                var nodeChildren = node.childNodes;
                data.previousFSCount = parseInt(attributes.getNamedItem("previousFSCount").value);
                data.currentFSCount = parseInt(attributes.getNamedItem("currentFSCount").value);
                data.gambleWon = data.currentFSCount > data.previousFSCount;
