initWheelList.source:
function (attr) {
            var list = [];
            var strings = attr.split("|");
            for (var i = 0; i < strings.length; i++) {
                if (strings[i] != "") {
                    list.push(parseInt(strings[i]));
                }
            }
            return list;
        }

