nextGamble.source:
function () {
            var logicResponse = this._server.getLogicResponse();
            if (logicResponse) {
                if (logicResponse.gambleData && !logicResponse.gambleData.gambleFinished) {
                    return true;
                }
            }
            return false;
        }

gambleReveal.source:
function () {
            _super.prototype.execute.call(this);
            var gambleFinished = this._server.getLogicResponse().gambleData.gambleFinished;
            //var gambleWon: boolean = this._server.getLogicResponse().gambleData.gambleWon;
            if (gambleFinished) {
                this._statesModel.gotoNextState();
            }
            else {
                this._statesModel.changeStateByName(game.FSGambleGameStates.IDLE_STATE);
            }
        }

gambleExit.source:
function () {
            _super.prototype.execute.call(this);
            var currentFS = this._server.getLogicResponse().gambleData.currentFSCount;
            if (this._bigBetStakes.getIsBigBet()) {
                if (currentFS == 0) {
                    this._statesModel.changeSubGame(game.SubGames.BIG_BET_GAME, game.BigBetGameStates.EXIT_FS_GAMBLE_STATE);
                }
                else {
                    this._statesModel.changeSubGame(game.SubGames.BIG_BET_GAME, game.BigBetGameStates.FREESPIN_ENTER_STATE);
                }
            }
            else {
                if (currentFS == 0) {
                    this._statesModel.gotoNextState();
                }
                else {
                    this._statesModel.changeSubGame(game.SubGames.BASE_GAME, game.BaseGameStates.FREESPIN_ENTER_STATE);
                }
            }
        }

gambleRequest.source:
function () {
            _super.prototype.execute.call(this);
            if (this._statesModel.getCurrentState().stateName == game.FSGambleGameStates.LOGIC_STATE) {
                var encoders = [
                    new game.GambleEncoder(this._fsGambleModel.collect),
                    new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
                ];
                var history = this._history.getNextState();
                if (history) {
                    encoders.push(new game.HistoryReplaceEncoder(history));
                }
                if (this._forceModel.forceSet) {
                    var forceEncoder = new game.GambleForceEncoder(this._forceModel.gambleWin);
                    encoders.push(forceEncoder);
                }
                this._forceModel.forceSet = false;
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
            else if (this._statesModel.getCurrentState().stateName == game.FSGambleGameStates.HISTORY_STATE) {
                var history = this._history.getNextState(false);
                var encoders = [
                    new game.GambleEncoder(this._fsGambleModel.collect),
                    new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
                ];
                if (history) {
                    encoders.push(new game.HistoryReplaceEncoder(history));
                }
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
        }

