normalRequest.source:
function () {
            _super.prototype.execute.call(this);
            if ((this._statesModel.getCurrentState().stateName == game.BaseGameStates.LOGIC_GLS_STATE ||
                this._statesModel.getCurrentState().stateName == game.FreespinsGameStates.LOGIC_GLS_STATE ||
                this._statesModel.getCurrentState().stateName == game.BigBetGameStates.LOGIC_GLS_STATE) &&
                !this._forceModel.forceOpen) {
                this._data.startPlay();
                var encoders = [
                    this.getStakeEncode(),
                    new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
                ];
                var history = this._history.getNextState();
                if (history) {
                    encoders.push(new game.HistoryReplaceEncoder(history));
                }
                if (this._forceModel.forceSet) {
                    var forceEncoder = new game.ForceEncoder(this._forceModel.reelData ? this._forceModel.reelData.positions : [0, 0, 0, 0, 0], this._forceModel.reelData ? this._forceModel.reelData.index : 0, this._forceModel.bonusDrumPosition ? this._forceModel.bonusDrumPosition : -1, this._forceModel.lowestSymbolAfterUpgrade ? this._forceModel.lowestSymbolAfterUpgrade : 0, this._forceModel.wildReels ? this._forceModel.wildReels : null, this._forceModel.canyonStopIndex >= 0 ? this._forceModel.canyonStopIndex : -1, this._forceModel.totemIndex >= 0 ? this._forceModel.totemIndex : -1, this._forceModel.totemStopIndex >= 0 ? this._forceModel.totemStopIndex : -1);
                    encoders.push(forceEncoder);
                }
                this._forceModel.forceSet = false;
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
            else if (this._statesModel.getCurrentState().stateName == game.PreGameStates.RECOVERY_STATE) {
                var encoders = [
                    this.getStakeEncode(),
                    new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
                ];
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
        }

