function (e) {
            this.view.getScene().getEngine().resize();
            if (this._server.getLogicResponse().bonusWheelData && !this._server.getLogicResponse().baseGameData.bonusChief) {
                this._commonui.stopAutoPlay();
                if (this._stageLoadeModel.getStageComplete(game.LoadingStages.BONUS_GAMES3)) {
                    this._partnerAdapter.hideProgressBar();
                    this.state = WheelMediator.STATE_RISING;
                    this.view.canvas2D.levelVisible = true;
                    this.raise();
                }
                else {
                    this._statesModel.changeStateByName(game.BaseGameStates.LOADING_BONUS);
                    this._partnerAdapter.showProgressBar();
                }
            }
            else {
                this._statesModel.gotoNextState();
            }
        }

