function () {
            var _this = this;
            _super.prototype.execute.call(this);
            if (this._serverModel.getLogicResponse().baseGameData.isMaxWin) {
                this._bigBetStakesModel.setIsBigBet(false);
                if (this._spinTypeModel.isCurrentSpinFS()) {
                    this._subgamesModel.crossFadeViews([
                        this._subgamesModel.basegameBgLayer,
                        this._subgamesModel.reelsLayer,
                        this._subgamesModel.basegameFrontLayer,
                        this._subgamesModel.transitionLayer,
                    ]);
                    TweenMax.delayedCall(1, function () {
                        _this.addCongrats();
                        _this.eventDispatcher.dispatchEvent(new game.GameEvent(game.GameEvent.MAX_WIN_DISPLAYED));
                    }, [], this);
                    TweenMax.delayedCall(6, function () {
                        _this._statesModel.changeSubGame(game.SubGames.BASE_GAME, game.BaseGameStates.END_GLS_STATE);
                        _this.eventDispatcher.dispatchEvent(new game.GameEvent(game.GameEvent.MAX_WIN_COMPLETE));
                    }, [], this);
                }
                else if (this._spinTypeModel.isCurrentSpinBigBet()) {
                    this.addCongrats();
                    this.eventDispatcher.dispatchEvent(new game.GameEvent(game.GameEvent.MAX_WIN_DISPLAYED));
                    TweenMax.delayedCall(6, function () {
                        _this._subgamesModel.crossFadeViews([
                            _this._subgamesModel.basegameBgLayer,
                            _this._subgamesModel.reelsLayer,
                            _this._subgamesModel.basegameFrontLayer,
                            _this._subgamesModel.transitionLayer,
                        ]);
                        _this._statesModel.changeSubGame(game.SubGames.BASE_GAME, game.BaseGameStates.END_GLS_STATE);
                        _this.eventDispatcher.dispatchEvent(new game.GameEvent(game.GameEvent.MAX_WIN_COMPLETE));
                    }, [], this);
                }
                else {
                    this.addCongrats();
                    this.eventDispatcher.dispatchEvent(new game.GameEvent(game.GameEvent.MAX_WIN_DISPLAYED));
                    TweenMax.delayedCall(6, function () {
                        _this._statesModel.changeStateByName(game.BaseGameStates.END_GLS_STATE);
                        _this.eventDispatcher.dispatchEvent(new game.GameEvent(game.GameEvent.MAX_WIN_COMPLETE));
                    }, [], this);
                }
            }
            else {
                this._statesModel.gotoNextState();
            }
        }
